const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Find the order
const order = db.prepare(\"SELECT * FROM orders WHERE order_id LIKE '%E0E671%'\").all();
console.log('=== ORDER ===');
console.log(JSON.stringify(order, null, 2));

if (order.length > 0) {
  const oid = order[0].order_id;

  // Get order items
  const items = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all(oid);
  console.log('\n=== ORDER ITEMS ===');
  console.log(JSON.stringify(items, null, 2));

  // Get order payments
  const payments = db.prepare('SELECT * FROM order_payments WHERE order_id = ?').all(oid);
  console.log('\n=== ORDER PAYMENTS ===');
  console.log(JSON.stringify(payments, null, 2));

  // Get fulfillments
  const fulfillments = db.prepare('SELECT * FROM order_fulfillments WHERE order_id = ?').all(oid);
  console.log('\n=== FULFILLMENTS ===');
  console.log(JSON.stringify(fulfillments, null, 2));
}
db.close();
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get product details
const product = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-73FAB4'\").get();
console.log('=== PRODUCT ===');
console.log(JSON.stringify(product, null, 2));

// Get variants
const variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = 'PROD-73FAB4'\").all();
console.log('\n=== VARIANTS (tau2Retail) ===');
console.log(JSON.stringify(variants, null, 2));

// Check for any other product-related tables
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('\n=== ALL TABLES ===');
console.log(tables.map(t => t.name).join(', '));

// Check if there's a products_details or specs table
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  if (cols.some(c => c.name.includes('spec') || c.name.includes('detail') || c.name.includes('description'))) {
    console.log('\nTable with specs/details:', t.name, '->', cols.map(c=>c.name));
  }
}
db.close();
"

